<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\TenantConfigDynamicRegistrationPolicyOptions;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigDynamicRegistrationPolicyAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigDynamicRegistrationPolicyAccessor trait.
 *
 * Covers null default, string/VO assignment via withDynamicRegistrationPolicy,
 * getDynamicRegistrationPolicy/dynamicRegistrationPolicy accessors, and isDynamicRegistrationPolicyChanged with/without original.
 */
class TenantConfigDynamicRegistrationPolicyAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDynamicRegistrationPolicy creates a new instance with the DynamicRegistrationPolicy set
     * from a string value, and getDynamicRegistrationPolicy returns the primitive string.
     */
    public function testWithDynamicRegistrationPolicyFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigDynamicRegistrationPolicyAccessorUnitTest();

        // Act
        $result = $holder->withDynamicRegistrationPolicy(TenantConfigDynamicRegistrationPolicyOptions::OPEN);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TenantConfigDynamicRegistrationPolicyOptions::OPEN, $result->getDynamicRegistrationPolicy());
    }
    /**
     * Asserts that withdynamicRegistrationPolicy has access to the value object
     * from a string value, and getDynamicRegistrationPolicy returns the primitive string.
     */
    public function testWithDynamicRegistrationPolicyFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigDynamicRegistrationPolicyAccessorUnitTest();

        // Act
        $result = $holder->withDynamicRegistrationPolicy(TenantConfigDynamicRegistrationPolicyOptions::OPEN);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TenantConfigDynamicRegistrationPolicyOptions::OPEN, $result->dynamicRegistrationPolicy()->value());
    }
    public function testChangedDynamicRegistrationPolicy(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigDynamicRegistrationPolicyAccessorUnitTest();
        $original = $holder->withDynamicRegistrationPolicy(TenantConfigDynamicRegistrationPolicyOptions::OPEN);
        $same = $holder->withDynamicRegistrationPolicy(TenantConfigDynamicRegistrationPolicyOptions::OPEN);
        $modified = $holder->withDynamicRegistrationPolicy(TenantConfigDynamicRegistrationPolicyOptions::TOKEN_REQUIRED);

        // Act
        $unchanged = $holder->isDynamicRegistrationPolicyChanged();
        $withSame = $original->isDynamicRegistrationPolicyChanged($same);
        $withDiferent = $original->isDynamicRegistrationPolicyChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigDynamicRegistrationPolicyAccessorUnitTest
{
    use TenantConfigDynamicRegistrationPolicyAccessor;
}
